// AI visibility plan (weekly, Monday 07:00, and on demand): one job per site — the brand names to look for, the competitors, the topics,
// the stored prompt set (seo_ai_prompts: stable week to week so the trend means something), whether new prompts must be written,
// the engines, the previous week's numbers and whether the monthly market view (DataForSEO LLM Mentions) is due.
// ---- shared by the monitors (AI Visibility Tracker, Backlink Monitor, Audit Scheduler; inlined by the build): which sites, with which settings ----
// Sites = the Data Table seo_sites ("Track my site") + every domain with a keyword ladder; settings per site from seo_monitors (defaults: everything on).
// On demand (Manual Run with { domain | site_id }) one site runs even when its weekly / monthly monitor is off; an untracked domain is checked ad hoc
// with the trigger's country, e-mail and callback.
let trigger = {}; try { const t = $('Manual Run').first(); trigger = (t && t.json) || {}; } catch (e) {}
if (trigger.body && typeof trigger.body === 'object') trigger = { ...trigger, ...trigger.body };
const rowsOf = (name) => { try { return $(name).all().map(i => i.json).filter(r => r && typeof r === 'object' && !r.error && Object.keys(r).length); } catch (e) { return []; } };
const normD = (x) => String(x || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const siteIdFor = (d) => 'site_' + d.replace(/[^a-z0-9]+/g, '-');
const listOf = (v) => (Array.isArray(v) ? v : String(v || '').split(/[\n,;]+/)).map(x => String(x).trim()).filter(Boolean);
const flag = (v, dflt) => (v === undefined || v === null || v === '') ? dflt : !(v === false || /^(false|0|no|off)$/i.test(String(v)));
const DEFAULT_ENGINES = ['chatgpt', 'perplexity', 'gemini', 'claude', 'ai_overview', 'ai_mode'];
function monitorSites(kind) {   // kind: 'ai' | 'backlinks' | 'audit'
  const sites = rowsOf('Load Sites').filter(r => r.site_id && r.domain), ladders = rowsOf('Load Ladders').filter(r => r.domain), mons = rowsOf('Load Monitors'), profiles = rowsOf('Load Profiles');
  const byDomain = new Map();
  for (const s of sites) { const d = normD(s.domain); if (d && !byDomain.has(d)) byDomain.set(d, { ...s, domain: d, keywords: listOf(s.keywords).map(k => k.toLowerCase()), virtual: false }); }
  for (const l of ladders) { const d = normD(l.domain); if (d && !byDomain.has(d)) byDomain.set(d, { site_id: siteIdFor(d), domain: d, country: l.country || '', location_code: Number(l.location_code) || 0, language_code: l.language_code || 'en', email: l.email || '', callback_url: l.callback_url || '', keywords: [], status: 'active', source: 'ladder', virtual: true }); }
  for (const s of byDomain.values()) { if (s.email && s.callback_url) continue; const l = ladders.find(l => normD(l.domain) === s.domain && (l.email || l.callback_url)); if (l) { s.email = s.email || l.email || ''; s.callback_url = s.callback_url || l.callback_url || ''; } }
  const want = normD(trigger.domain) || String(trigger.site_id || '').trim();
  let list = [...byDomain.values()];
  if (want) {
    list = list.filter(s => s.domain === want || s.site_id === want);
    if (!list.length && normD(trigger.domain)) list = [{ site_id: siteIdFor(normD(trigger.domain)), domain: normD(trigger.domain), country: trigger.country || '', location_code: Number(trigger.location_code) || 0, language_code: trigger.language_code || 'en', email: '', callback_url: '', keywords: [], status: 'active', source: 'adhoc', virtual: true, adhoc: true }];
  } else list = list.filter(s => String(s.status || 'active') !== 'paused');
  const out = list.map(s => {
    const m = mons.find(x => x.site_id === s.site_id) || {};
    const p = profiles.find(x => x.site_id === s.site_id) || {};
    const engines = listOf(m.ai_engines).map(e => e.toLowerCase()).filter(e => DEFAULT_ENGINES.includes(e));
    const settings = { ai_visibility: flag(m.ai_visibility, true), backlinks: flag(m.backlinks, true), audit_monthly: flag(m.audit_monthly, true), engines: engines.length ? engines : DEFAULT_ENGINES,
      prompts_max: Math.min(15, Math.max(3, Number(m.ai_prompts_max) || 8)), audit_pages: Math.min(1000, Math.max(50, Number(m.audit_pages) || 200)), audit_js: flag(m.audit_js, false),
      competitors: [...new Set([...listOf(m.competitors), ...listOf(trigger.competitors)].map(normD).filter(d => d && d !== s.domain))].slice(0, 5),
      brand_names: [...new Set([...listOf(m.brand_names), ...listOf(trigger.brand_names), p.business_name || ''].map(x => String(x).trim()).filter(Boolean))], stored: !!m.site_id };
    const o = { ...s, settings, profile: { business_name: p.business_name || '', business_type: p.business_type || '', city: p.city || '', phone: p.phone || '', street_address: p.street_address || '', author_name: p.author_name || '' } };
    if (want) { if (trigger.email) o.email = trigger.email; if (trigger.callback_url) o.callback_url = trigger.callback_url; if (trigger.country) o.country = trigger.country; if (Number(trigger.location_code)) o.location_code = Number(trigger.location_code); if (trigger.language_code) o.language_code = trigger.language_code; }
    o.request_id = String(trigger.request_id || s.request_id || '');
    return o;
  });
  const flagOf = { ai: 'ai_visibility', backlinks: 'backlinks', audit: 'audit_monthly' }[kind];
  return { list: want ? out : out.filter(s => s.settings[flagOf]), on_demand: !!want, want, trigger, total: byDomain.size };
}

const CONFIG = { max_sites_per_run: 15, max_topics: 8 };
const { list, on_demand, want, total } = monitorSites('ai');
if (!list.length) return [{ json: { nothing_to_do: true, reason: on_demand ? 'no site matches "' + want + '"' : (total ? 'AI visibility is switched off for every site' : 'no sites yet (register one through "Track my site" or plan a keyword ladder)') } }];
const promptRows = rowsOf('Load AI Prompts'), visRows = rowsOf('Load AI Visibility'), ladders = rowsOf('Load Ladders');
const now = new Date(); const iso = now.toISOString(); const month = iso.slice(0, 7);
return list.slice(0, CONFIG.max_sites_per_run).map(s => {
  const label = s.domain.split('.')[0];
  const brand_names = [...new Set([s.domain, ...(s.settings.brand_names || []), ...(label.length >= 5 ? [label] : [])].map(x => String(x).trim()).filter(x => x.length >= 3))];
  const lrows = ladders.filter(l => normD(l.domain) === s.domain).sort((a, b) => (Number(a.rung) || 0) - (Number(b.rung) || 0));
  const asked = on_demand ? listOf(trigger.topics).map(x => x.toLowerCase()) : [];   // "Main services or products" on the on-demand form / API `topics`
  const topics = [...new Set([...asked, ...lrows.map(l => String(l.head_keyword || '').toLowerCase().trim()), ...(s.keywords || []), ...lrows.filter(l => Number(l.rung) !== 4).map(l => String(l.keyword || '').toLowerCase().trim())].filter(Boolean))].slice(0, CONFIG.max_topics);
  const mine = promptRows.filter(p => p.site_id === s.site_id && String(p.status || 'active') !== 'off' && p.prompt);
  const custom = mine.filter(p => p.source === 'custom'), auto = mine.filter(p => p.source !== 'custom');
  const prev = visRows.filter(v => v.site_id === s.site_id).sort((a, b) => String(b.checked_at).localeCompare(String(a.checked_at)))[0] || null;
  const parse = (t, d) => { try { return JSON.parse(t || ''); } catch (e) { return d; } };
  const autoRivals = prev ? (parse(prev.competitors_json, []) || []).filter(c => c && c.domain && c.auto && (c.mentions || 0) >= 2).map(c => c.domain) : [];
  const competitors = [...new Set([...s.settings.competitors, ...autoRivals])].slice(0, 8);
  const room = Math.max(0, s.settings.prompts_max - custom.length);
  const deficit = Math.max(0, room - auto.length);
  const need = (!auto.length || deficit >= 2) ? deficit : 0;   // top up only when 2+ questions are missing (not every week for one)
  return { json: { site_id: s.site_id, domain: s.domain, country: s.country || '', location_code: Number(s.location_code) || 2840, language_code: s.language_code || 'en', email: s.email || '', callback_url: s.callback_url || '',
    request_id: s.request_id || '', on_demand, adhoc: !!s.adhoc, business_name: s.profile.business_name || '', business_type: s.profile.business_type || '', city: s.profile.city || '',
    brand_names, competitors, configured_competitors: s.settings.competitors, topics, engines: s.settings.engines, prompts_max: s.settings.prompts_max,
    prompts: [...custom, ...auto].slice(0, s.settings.prompts_max).map(p => ({ prompt_id: p.prompt_id, prompt: p.prompt, kind: p.kind || 'custom', topic: p.topic || '', keyword: p.keyword || '', source: p.source || 'auto' })),
    need_prompts: need > 0, prompts_needed: need, need_site_text: need > 0 && !topics.length && !s.profile.business_name, market_due: !!topics.length && (!prev || String(prev.market_month || '') !== month), market_keyword: topics[0] || '',
    previous: prev ? { checked_at: prev.checked_at, mention_rate: Number(prev.mention_rate), citation_rate: Number(prev.citation_rate), share_of_voice: Number(prev.share_of_voice), avg_rank: Number(prev.avg_rank), engines: parse(prev.engines_json, {}), market_month: prev.market_month || '', market: parse(prev.market_json, null) } : null,
    run_id: 'ai_' + iso.slice(0, 10).replace(/-/g, '') + '_' + s.site_id.replace(/^site_/, ''), checked_at: iso } };
});

// Sites that need questions but have no topics and no business name on file (e.g. an ad-hoc check of a new domain): the homepage is read
// (Jina Reader) so the Prompt Writer knows what the business sells.
const jobs = $('AI Plan').all().map(i => i.json).filter(p => p.need_site_text && !p.nothing_to_do);
return jobs.length ? jobs.map(p => ({ json: { site_id: p.site_id, domain: p.domain } })) : [{ json: { skip: true } }];

// Sites whose prompt set is short get one Prompt Writer job each (Claude writes the buyer questions once; they are stored and reused weekly).
const jobs = $('AI Plan').all().map(i => i.json).filter(p => p.need_prompts && !p.nothing_to_do);
if (!jobs.length) return [{ json: { skip: true } }];
let reads = [], texts = []; try { reads = $('Site Text Jobs').all().map(i => i.json).filter(j => !j.skip); texts = $('Read Site (AI)').all().map(i => String((i.json || {}).site_text || '')); } catch (e) {}
const textOf = (id) => { const k = reads.findIndex(r => r.site_id === id); return k >= 0 ? (texts[k] || '').replace(/\n{3,}/g, '\n\n').slice(0, 3500) : ''; };
return jobs.map(p => ({ json: { site_id: p.site_id, domain: p.domain, business_name: p.business_name || p.domain, business_type: p.business_type || '', country: p.country || '', city: p.city || '',
  topics: p.topics, count: p.prompts_needed, existing: p.prompts.map(x => x.prompt), has_brand_prompt: p.prompts.some(x => x.kind === 'brand'), site_text: textOf(p.site_id) } }));

parameters.text:
=You write the questions real buyers type into ChatGPT, Perplexity, Gemini and Google's AI Mode before they choose a provider. These questions are asked every week to measure whether the business below is recommended or cited by AI assistants, so they must be realistic, varied and stable.

BUSINESS
Name: {{ $json.business_name }} · Website: {{ $json.domain }} · Type: {{ $json.business_type || 'see the topics' }}
Market: {{ $json.country || 'not given' }}{{ $json.city ? ' (' + $json.city + ')' : '' }}
Topics it wants to be found for: {{ ($json.topics || []).join(' · ') || 'infer from the website name' }}
{{ $json.site_text ? 'WEBSITE TEXT (the homepage, to understand what the business sells):\n' + $json.site_text + '\n' : '' }}Questions already tracked (do not repeat or rephrase them): {{ ($json.existing || []).join(' | ') || 'none' }}

Write exactly {{ $json.count }} new questions. Mix these kinds across the topics, most valuable first:
- recommend: "Which companies / who are the best … in <market>?" — the questions where AI lists providers
- choose: how to choose, what to look for, red flags
- cost: price, cost, fees, budget
- compare: X vs Y, alternatives, which option is better for a given situation
- problem: the problem the buyer wants solved, in their words (deadline, regulation, failure, migration)
{{ $json.has_brand_prompt ? '' : '- brand: exactly one question asking what ' + $json.business_name + ' (' + $json.domain + ') is and offers — this checks whether AI knows the brand' }}

Rules: plain buyer language, 8-22 words, the market named where the buyer would name it, no other company names unless the topic itself is a product comparison, never the business name except in the single brand question. For each question also give a short Google search phrase (2-6 words) for the same intent, and the topic it belongs to.

Return ONLY JSON: {"prompts": [{"prompt": "", "kind": "recommend | choose | cost | compare | problem | brand", "topic": "", "keyword": ""}]}

parameters.jsCode:
// New prompt rows for seo_ai_prompts: the Prompt Writer's questions (Claude), or template questions when the writer failed or did not run.
// Exact table columns. Existing prompts are never rewritten, so the weekly trend compares the same questions.
const plans = $('AI Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
let jobs = []; try { jobs = $('Prompt Jobs').all().map(i => i.json).filter(j => !j.skip); } catch (e) {}
let outs = []; try { outs = $('Prompt Writer').all().map(i => i.json); } catch (e) {}
const parse = (raw) => { if (raw && typeof raw === 'object') return raw; const s = String(raw || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, ''); try { return JSON.parse(s); } catch (e) { const a = s.indexOf('{'), b = s.lastIndexOf('}'); try { return JSON.parse(s.slice(a, b + 1)); } catch (e2) { return null; } } };
const hash = (t) => { let h = 5381; for (const c of String(t)) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return h.toString(36); };
const norm = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const now = new Date().toISOString(); const rows = [];
const KINDS = ['recommend', 'choose', 'cost', 'compare', 'problem', 'brand'];
for (const p of plans) {
  if (!p.need_prompts) continue;
  const ji = jobs.findIndex(j => j.site_id === p.site_id);
  const got = ji >= 0 && outs[ji] && !outs[ji].error ? parse(outs[ji].output) : null;
  let qs = (got && Array.isArray(got.prompts) ? got.prompts : []).filter(q => q && q.prompt && String(q.prompt).length >= 12).map(q => ({ prompt: String(q.prompt).trim().slice(0, 300), kind: KINDS.includes(String(q.kind).toLowerCase()) ? String(q.kind).toLowerCase() : 'recommend', topic: String(q.topic || '').slice(0, 120), keyword: String(q.keyword || q.topic || '').toLowerCase().slice(0, 120), source: 'auto' }));
  if (!qs.length) {   // template fallback: the same buyer journey, less natural wording
    const where = p.country ? ' in ' + (p.city || p.country) : '';
    for (const t of (p.topics.length ? p.topics : [p.domain.split('.')[0]]).slice(0, 4)) qs.push({ prompt: 'Which companies offer ' + t + where + '? Recommend the best options with their websites.', kind: 'recommend', topic: t, keyword: t, source: 'template' }, { prompt: 'How do I choose a provider for ' + t + where + ', and what should it cost?', kind: 'choose', topic: t, keyword: t + ' cost', source: 'template' });
    if (!p.prompts.some(x => x.kind === 'brand')) qs.unshift({ prompt: 'What is ' + (p.business_name || p.domain) + ' (' + p.domain + ') and what does it offer?', kind: 'brand', topic: 'brand', keyword: p.business_name || p.domain.split('.')[0], source: 'template' });
  }
  const have = new Set(p.prompts.map(x => norm(x.prompt)));
  for (const q of qs) { if (rows.filter(r => r.site_id === p.site_id).length >= p.prompts_needed) break; if (have.has(norm(q.prompt))) continue; have.add(norm(q.prompt));
    rows.push({ prompt_id: 'p_' + hash(p.site_id + '|' + norm(q.prompt)), site_id: p.site_id, domain: p.domain, prompt: q.prompt, kind: q.kind, topic: q.topic, keyword: q.keyword || q.topic, source: q.source, status: 'active', created_at: now }); }
}
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { skip: true } }];

// One DataForSEO request per question x engine (ChatGPT = the real chatgpt.com answer through the LLM scraper; Perplexity, Gemini and Claude =
// LLM Responses with web search; Google AI Mode with the question; the Google AI Overview on the matching search phrase), plus the monthly market
// view (LLM Mentions: which domains AI answers cite for the main topic). Costs measured live on 2026-10-02.
const CONFIG = { max_requests_per_run: 500, max_cost_per_run_usd: 12,
  models: { perplexity: 'sonar', gemini: 'gemini-3.5-flash', claude: 'claude-haiku-4-5' },
  cost: { chatgpt: 0.004, perplexity: 0.006, gemini: 0.035, claude: 0.025, ai_overview: 0.002, ai_mode: 0.004, market: 0.115 } };
const API = 'https://api.dataforseo.com/v3/';
const plans = $('AI Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
let fresh = []; try { fresh = $('Prompt Rows').all().map(i => i.json).filter(r => !r.skip && r.prompt_id); } catch (e) {}
const out = []; let spend = 0; const skipped = [];
const add = (p, q, engine, endpoint, body) => {
  const c = CONFIG.cost[engine] || 0.01;
  if (out.length >= CONFIG.max_requests_per_run || spend + c > CONFIG.max_cost_per_run_usd) { skipped.push(p.domain + ':' + engine); return; }
  spend += c; out.push({ json: { site_id: p.site_id, domain: p.domain, run_id: p.run_id, prompt_id: q.prompt_id, prompt: q.prompt, kind: q.kind, topic: q.topic, keyword: q.keyword, engine, endpoint: API + endpoint, body, est_cost: c } });
};
for (const p of plans) {
  const qs = [...p.prompts, ...fresh.filter(r => r.site_id === p.site_id).map(r => ({ prompt_id: r.prompt_id, prompt: r.prompt, kind: r.kind, topic: r.topic, keyword: r.keyword, source: r.source }))].slice(0, p.prompts_max);
  const loc = { location_code: p.location_code, language_code: p.language_code };
  const seenKw = new Set();
  for (const q of qs) {
    const e = p.engines;
    if (e.includes('chatgpt')) add(p, q, 'chatgpt', 'ai_optimization/chat_gpt/llm_scraper/live/advanced', [{ keyword: q.prompt, ...loc }]);
    if (e.includes('perplexity')) add(p, q, 'perplexity', 'ai_optimization/perplexity/llm_responses/live', [{ user_prompt: q.prompt, model_name: CONFIG.models.perplexity, max_output_tokens: 1000 }]);
    if (e.includes('gemini')) add(p, q, 'gemini', 'ai_optimization/gemini/llm_responses/live', [{ user_prompt: q.prompt, model_name: CONFIG.models.gemini, web_search: true, max_output_tokens: 1200 }]);
    if (e.includes('claude')) add(p, q, 'claude', 'ai_optimization/claude/llm_responses/live', [{ user_prompt: q.prompt, model_name: CONFIG.models.claude, web_search: true, max_output_tokens: 1200 }]);
    if (e.includes('ai_mode')) add(p, q, 'ai_mode', 'serp/google/ai_mode/live/advanced', [{ keyword: q.prompt, ...loc }]);
    const kw = String(q.keyword || '').trim().toLowerCase();
    if (e.includes('ai_overview') && kw && q.kind !== 'brand' && !seenKw.has(kw)) { seenKw.add(kw); add(p, q, 'ai_overview', 'serp/google/organic/live/advanced', [{ keyword: kw, ...loc, depth: 10, load_async_ai_overview: true }]); }
  }
  if (p.market_due && p.market_keyword) add(p, { prompt_id: 'market', prompt: p.market_keyword, kind: 'market', topic: p.market_keyword, keyword: p.market_keyword }, 'market', 'ai_optimization/llm_mentions/top_domains/live', [{ target: [{ keyword: p.market_keyword }], ...loc, limit: 15 }]);
}
if (!out.length) return [{ json: { skip: true, reason: plans.length ? 'no questions to ask (no topics and no business name on file)' : 'nothing to do', skipped } }];
out[0].json.skipped_by_cap = skipped;
return out;

// One row per question x engine for seo_ai_answers (exact columns): did the answer mention the brand, cite one of your pages, at which rank
// among the businesses it names, which competitors / businesses appeared and which sources it cited. The market view (LLM Mentions) is
// read by AI Metrics, not stored here. Engines: chatgpt (llm_scraper), perplexity / gemini / claude (llm_responses), ai_overview / ai_mode (SERP).
const reqs = $('AI Requests').all().map(i => i.json);
const resps = $input.all().map(i => i.json || {});
if (!reqs.length || reqs[0].skip) return [{ json: { skip: true } }];
const plans = $('AI Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const now = new Date().toISOString();
const hostOf = (u) => { const m = String(u || '').match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };   // no URL constructor in the n8n sandbox
const cleanUrl = (u) => String(u || '').replace(/[?&](utm_[a-z]+|srsltid)=[^&#]*/gi, '').replace(/\?&/, '?').replace(/\?$/, '');
const DOMAIN_RE = /\b((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:com|net|org|io|ai|co|ae|sa|qa|om|kw|bh|eg|uk|de|fr|es|it|nl|in|pk|sg|au|ca|nz|za|br|mx|us|biz|info|tech|app|cloud|global|digital|solutions|consulting|agency|me))\b/gi;
// sources AI cites that are not businesses competing for the client's buyers (they are PR / listing targets instead)
const GENERIC = /(^|\.)(wikipedia\.org|wikimedia\.org|youtube\.com|youtu\.be|linkedin\.com|facebook\.com|instagram\.com|x\.com|twitter\.com|tiktok\.com|reddit\.com|quora\.com|medium\.com|github\.com|google\.com|goo\.gl|bing\.com|apple\.com|amazon\.com|forbes\.com|reuters\.com|bloomberg\.com|gulfnews\.com|khaleejtimes\.com|thenationalnews\.com|zawya\.com|arabianbusiness\.com|gartner\.com|g2\.com|capterra\.com|trustpilot\.com|clutch\.co|glassdoor\.com|indeed\.com|statista\.com|pwc\.com|kpmg\.com|deloitte\.com|ey\.com|vertexaisearch\.cloud\.google\.com|chatgpt\.com|openai\.com|perplexity\.ai|anthropic\.com|claude\.ai|gemini\.google\.com)$|\.gov(\.[a-z]{2})?$|\.edu(\.[a-z]{2})?$|\.ac\.[a-z]{2}$|(^|\.)u\.ae$|\.int$/i;
const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const rows = [];
reqs.forEach((q, i) => {
  if (q.engine === 'market') return;
  const plan = plans.find(p => p.site_id === q.site_id) || { brand_names: [q.domain], competitors: [], domain: q.domain };
  const r = resps[i] || {}; const task = (r.tasks || [])[0] || {}; const res = (task.result || [])[0] || null;
  let text = '', cites = [], answered = false, error = '';
  if (r.error || !task.status_code) error = String((r.error && (r.error.message || r.error)) || 'no response').slice(0, 200);
  else if (task.status_code !== 20000) error = String(task.status_message || task.status_code).slice(0, 200);
  else if (res) {
    if (q.engine === 'chatgpt') { text = String(res.markdown || (res.items || []).map(x => x.markdown || x.text || '').join('\n')); cites = (res.sources || []).map(s => ({ url: s.url, host: hostOf(s.url) || String(s.domain || '').replace(/^www\./, '') })); answered = !!text; }
    else if (q.engine === 'ai_overview' || q.engine === 'ai_mode') {
      const ao = (res.items || []).find(x => x && x.type === 'ai_overview');
      if (ao) { text = String(ao.markdown || (ao.items || []).map(x => x.markdown || x.text || '').join('\n'));
        const refs = [...(ao.references || []), ...(ao.items || []).flatMap(x => x.references || [])];
        cites = refs.map(x => ({ url: x.url, host: hostOf(x.url) || String(x.domain || '').replace(/^www\./, '') })); answered = !!(text || cites.length); }
    } else {   // llm_responses: sections with text + annotations (Gemini annotations point to a Google redirect; their title is the source domain)
